import { ArrowUpRight } from 'lucide-react';

export function Value() {
  return <section id="comunidad" className="value-section section-rail" aria-labelledby="value-heading">
    <div className="section-label"><span>01 / LA COMUNIDAD</span><span>EL VALOR ESTÁ EN CONECTAR</span></div>
    <div className="value-grid"><div className="value-copy"><h2 id="value-heading">No tienes que<br/>hacerlo <em>todo.</em><br/>Ni hacerlo <em>solo.</em></h2><p>Hay ideas que necesitan una mirada distinta. Personas con habilidades que buscan un propósito. Y recursos que pueden llegar más lejos cuando se comparten.</p><p>hago.click reúne esas posibilidades alrededor de algo concreto: hacer que un proyecto avance. Una conversación, un conocimiento o una herramienta pueden ser el comienzo.</p><a className="text-link" href="#participar">Encuentra tu forma de participar <ArrowUpRight size={18}/></a></div><figure className="connection-exhibit"><div className="exhibit-heading"><span>FIG. 01 — EL PUNTO DE ENCUENTRO</span><span>+</span></div><img src="https://images.hostinger.com/bba8bde2-1477-49df-aa06-3f71ce33c6ea/bba88a90-5130-4b10-a1db-0fe04f50a804.png" srcSet="https://images.hostinger.com/bba8bde2-1477-49df-aa06-3f71ce33c6ea/bba88a90-5130-4b10-a1db-0fe04f50a804.png?width=375 375w, https://images.hostinger.com/bba8bde2-1477-49df-aa06-3f71ce33c6ea/bba88a90-5130-4b10-a1db-0fe04f50a804.png?width=768 768w, https://images.hostinger.com/bba8bde2-1477-49df-aa06-3f71ce33c6ea/bba88a90-5130-4b10-a1db-0fe04f50a804.png?width=1024 1024w, https://images.hostinger.com/bba8bde2-1477-49df-aa06-3f71ce33c6ea/bba88a90-5130-4b10-a1db-0fe04f50a804.png 1344w" sizes="(min-width: 900px) 46vw, 100vw" alt="Piezas de cristal menta y bloques oscuros conectados: una representación de ideas y recursos que se encuentran." width={1344} height={768} loading="lazy"/><figcaption><span>IDEA + CONOCIMIENTO + RECURSOS</span><strong>Más posibilidades, juntos.</strong></figcaption></figure></div>
  </section>;
}

