@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 60 14% 97%;
    --foreground: 165 12% 11%;
    --card: 60 14% 97%;
    --card-foreground: 165 12% 11%;
    --popover: 60 14% 97%;
    --popover-foreground: 165 12% 11%;
    --primary: 153 64% 75%;
    --primary-foreground: 165 12% 11%;
    --secondary: 150 13% 92%;
    --secondary-foreground: 165 12% 11%;
    --muted: 150 13% 92%;
    --muted-foreground: 160 5% 39%;
    --accent: 153 64% 75%;
    --accent-foreground: 165 12% 11%;
    --destructive: 0 70% 45%;
    --destructive-foreground: 0 0% 100%;
    --border: 160 7% 81%;
    --input: 160 7% 81%;
    --ring: 160 35% 36%;
    --radius: 0.5rem;
    --mint: #97e8be;
    --ink: #19221e;
    --paper: #f7f8f4;
    --quiet: #5b645e;
    --line: #d4d9d3;
    --dark-line: #3a4840;
    --dark-muted: #b5c4ba;
  }
  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; scroll-padding-top: 32px; }
  body { margin: 0; font-family: 'Manrope', sans-serif; background: var(--paper); color: var(--ink); -webkit-font-smoothing: antialiased; overflow-x: clip; }
  a { color: inherit; text-decoration: none; }
  button { font: inherit; cursor: pointer; }
  button, a, summary { -webkit-tap-highlight-color: transparent; }
  button:focus-visible, a:focus-visible, summary:focus-visible { outline: 3px solid #388462; outline-offset: 5px; }
  h1, h2, h3, h4, p, figure { margin: 0; }
  ::selection { background: var(--mint); color: var(--ink); }
}

